Estas instrucciones están envueltas en FQuestItemComponentDebuggerDisplayData con un componente que almacena todas las instrucciones que deben incluirse juntas.
Ejemplo de instrucciones: escribe el texto "Este es un mensaje de prueba: " en blanco, seguido de "¡Hola, mundo!" en verde en la misma línea.

FQuestItemComponentDebuggerDisplayData DisplayData;
DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::PushStyleColor, QuestItemComponentDebugStrings::Color_White));
DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::NewLineText, TEXT("Este es un mensaje de prueba: ")));
DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::PopStyleColor));

DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::PushStyleColor, QuestItemComponentDebugStrings::Color_Green));
DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::SameLineText, TEXT("¡Hola, mundo!")));
DisplayData.DrawData.Add(FQuestItemComponentDebugDrawData(EQuestItemComponentDebugStyleType::PopStyleColor));

